async function derive(pass,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:600000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encryptBytes(bytes,pass){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await derive(pass,salt),cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,bytes));return {v:1,salt:b64(salt),iv:b64(iv),data:b64(cipher)}}
async function decryptBytes(payload,pass){const key=await derive(pass,unb64(payload.salt));return new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(payload.iv)},key,unb64(payload.data)))}
function b64(bytes){let bin='';bytes.forEach(b=>bin+=String.fromCharCode(b));return btoa(bin)}function unb64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}function toHex(bytes){return [...bytes].map(b=>b.toString(16).padStart(2,'0')).join('').toUpperCase()}function fromHex(s){if(!/^(?:[0-9A-F]{2})+$/i.test(s))throw Error('Invalid hex layer');return Uint8Array.from(s.match(/.{2}/g),x=>parseInt(x,16))}
const NIBBLES=['😀','😃','😄','😁','😆','😅','😂','🙂','🙃','😉','😊','😇','🥰','😍','🤩','😘'];
function bytesEmoji(bytes){return [...bytes].map(b=>NIBBLES[b>>4]+NIBBLES[b&15]).join('') }function emojiBytes(s){const list=[...s].filter(c=>NIBBLES.includes(c));if(list.length%2)throw Error('Emoji payload is incomplete');const out=new Uint8Array(list.length/2);for(let i=0;i<list.length;i+=2)out[i/2]=(NIBBLES.indexOf(list[i])<<4)|NIBBLES.indexOf(list[i+1]);return out}
async function saveBook(pass){if(pass.length<10)return toast('Use at least 10 characters for storage passphrase');try{const payload=await encryptBytes(new TextEncoder().encode(JSON.stringify(book)),pass);localStorage.setItem('morse-encrypted-book',JSON.stringify(payload));toast('Codebook encrypted and saved locally')}catch(e){toast('Could not save encrypted codebook')}}
async function loadBook(pass){try{const raw=localStorage.getItem('morse-encrypted-book');if(!raw)throw Error('No saved codebook');book=JSON.parse(new TextDecoder().decode(await decryptBytes(JSON.parse(raw),pass)));renderBookMap();toast('Saved codebook unlocked')}catch{toast('Could not unlock: wrong passphrase or damaged data')}}
function setupSecure(){const input=$('#secure-input'),pass=$('#secure-pass'),output=$('#secure-output'),status=$('#secure-status');if(roomKey)pass.value=roomKey;$('#secure-run').onclick=async()=>{if(!pass.value)return toast('Enter your shared passphrase');try{status.textContent='Working…';if($('#secure-action').value==='encrypt'){const payload=await encryptBytes(new TextEncoder().encode(input.value),pass.value);let bytes=new TextEncoder().encode(JSON.stringify(payload));let result=bytesEmoji(bytes);if($('#secure-layer').value==='morse')result=encode(toHex(new TextEncoder().encode(result)));secureOutput=result;output.textContent=result;status.textContent='Encrypted · AES-256-GCM'}else{let raw=input.value.trim();if($('#secure-layer').value==='morse'){raw=decode(raw);raw=new TextDecoder().decode(fromHex(raw))}const payload=JSON.parse(new TextDecoder().decode(emojiBytes(raw)));secureOutput=new TextDecoder().decode(await decryptBytes(payload,pass.value));output.textContent=secureOutput;status.textContent='Authenticated · decrypted'}pushHistory('secure',status.textContent)}catch(e){output.textContent='Authentication failed. The passphrase is incorrect, or the encrypted message has been modified or corrupted.';status.textContent='Decryption failed';secureOutput='';} };$('#secure-clear').onclick=()=>{input.value='';pass.value='';output.textContent='Cleared';secureOutput='';status.textContent='Cleared'};$('#secure-copy').onclick=()=>copy(secureOutput);$('#secure-download').onclick=()=>download(secureOutput,'secure-message.txt');$('#secure-share').onclick=()=>{if(!secureOutput)return toast('Encrypt a message first');const url=location.origin+'/cipher#payload='+encodeURIComponent(secureOutput);copy(url);toast('Encrypted payload link copied')}}
function setupRoom(){const fragment=new URLSearchParams(location.hash.slice(1));const key=fragment.get('room');roomKey=key;if(key){$('#room-state').textContent='Room key detected locally. It is not sent to the server.'}$('#room-create').onclick=()=>{const bytes=crypto.getRandomValues(new Uint8Array(32));roomKey=b64(bytes);const url=location.origin+'/cipher#room='+encodeURIComponent(roomKey);$('#room-link').value=url;$('#room-state').textContent='New random room key generated. Share this complete link privately.'};$('#room-copy').onclick=()=>copy($('#room-link').value);$('#room-clear').onclick=()=>{roomKey=null;history.replaceState(null,'',location.pathname);$('#room-state').textContent='Room key cleared from this page.'};if(roomKey)$('#room-state').textContent='Room key detected locally. Use it as the Secure-mode passphrase.'}
function exportShareCard(message,format){const w=1080,h=format==='story'?1920:1080,c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#080d18';x.fillRect(0,0,w,h);x.fillStyle='#b5f477';x.fillRect(80,90,84,84);x.fillStyle='#12200a';x.font='bold 54px Arial';x.fillText('M',102,152);x.fillStyle='#f3f6fc';x.font='bold 44px Arial';x.fillText('MORSE.',190,150);x.fillStyle='#b5f477';x.font='bold 60px Arial';x.fillText('A message in symbols.',80,h*.4);x.fillStyle='#f3f6fc';x.font='38px Arial';(String(message||'Your private signal starts here.').match(/.{1,24}/g)||[]).slice(0,14).forEach((line,i)=>x.fillText(line,80,h*.5+i*58));x.fillStyle='#94a4ba';x.font='25px Arial';x.fillText('Built by CloudExify · Code Your Future',80,h-90);c.toBlob(b=>download(b,format==='story'?'morse-story.png':'morse-square.png','image/png'))}
