function downloadWav(code){const wpm=Math.max(5,Math.min(40,+($('#wpm')?.value||15))),freq=Math.max(300,Math.min(1200,+($('#freq')?.value||620))),dot=1.2/wpm,sr=44100;let duration=0;for(const c of code)duration+=c==='.'?2*dot:c==='-'?4*dot:c==='/'?7*dot:3*dot;const samples=Math.ceil((duration+.2)*sr),buffer=new ArrayBuffer(44+samples*2),view=new DataView(buffer);const write=(o,t)=>[...t].forEach((c,i)=>view.setUint8(o+i,c.charCodeAt(0)));write(0,'RIFF');view.setUint32(4,36+samples*2,true);write(8,'WAVE');write(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,sr,true);view.setUint32(28,sr*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);write(36,'data');view.setUint32(40,samples*2,true);let cursor=0;for(const c of code){const on=c==='.'?dot:c==='-'?3*dot:0,off=c==='.'?dot:c==='-'?dot:c==='/'?7*dot:3*dot;if(on){const n=Math.floor(on*sr);for(let i=0;i<n&&cursor+i<samples;i++){const fade=Math.min(1,i/150,(n-i)/150);view.setInt16(44+(cursor+i)*2,Math.sin(2*Math.PI*freq*i/sr)*.22*Math.max(0,fade)*32767,true)}cursor+=n}cursor+=Math.floor(off*sr)}download(new Blob([buffer],{type:'audio/wav'}),'morse-signal.wav','audio/wav')}
function playMorse(code){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return toast('Audio unavailable');const wpm=Math.max(5,Math.min(40,+($('#wpm')?.value||15))),fwpm=Math.max(5,Math.min(wpm,+($('#fwpm')?.value||wpm))),freq=Math.max(300,Math.min(1200,+($('#freq')?.value||620)));const dot=1.2/wpm,extra=Math.max(0,1.2/fwpm-dot),ctx=new AC();let t=ctx.currentTime+.05;for(const ch of code){if(ch==='.'||ch==='-'){let d=ch==='.'?dot:3*dot;const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.14,t+.006);g.gain.setValueAtTime(.14,t+d-.006);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+d);t+=d+dot}else if(ch==='/')t+=7*dot+6*extra;else t+=3*dot+2*extra}setTimeout(()=>ctx.close(),Math.max(500,(t-ctx.currentTime)*1000+200))}
