function setupAppLock(){
 const lockKey='morse-app-lock-v1';
 document.body.insertAdjacentHTML('beforeend',`<section class="app-lock-screen" id="app-lock-screen" hidden><div class="app-lock-card" role="dialog" aria-modal="true" aria-labelledby="app-lock-title"><span class="eyebrow">LOCAL APP LOCK</span><h2 id="app-lock-title">This studio is locked.</h2><p>Enter your local PIN to unlock this browser session. The PIN is checked locally.</p><label for="app-unlock-pin">App PIN</label><input id="app-unlock-pin" type="password" autocomplete="current-password" inputmode="text"><div class="app-lock-actions"><button class="button button-primary" id="app-unlock">Unlock studio</button><button class="mini-button button-danger" id="app-lock-panic">Panic wipe</button></div><p class="app-lock-error" id="app-lock-error" role="status" aria-live="polite"></p></div></section>`);
 const overlay=$('#app-lock-screen'),pinInput=$('#app-unlock-pin'),error=$('#app-lock-error');
 const show=()=>{overlay.hidden=false;pinInput.value='';error.textContent='';setTimeout(()=>pinInput.focus(),20)};
 const hide=()=>{overlay.hidden=true;sessionStorage.setItem('morse-app-unlocked','1')};
 if(localStorage.getItem(lockKey)&&sessionStorage.getItem('morse-app-unlocked')!=='1')show();
 $('#app-lock')?.addEventListener('click',async()=>{
   try{
     let saved=localStorage.getItem(lockKey);
     if(!saved){const pin=prompt('Create a local app-lock PIN (at least 6 characters).');if(!pin)return;if(pin.length<6){toast('PIN must contain at least 6 characters');return}const confirmPin=prompt('Confirm your app-lock PIN.');if(pin!==confirmPin){toast('PINs did not match');return}saved=JSON.stringify(await MorseCrypto.sealVault({purpose:'morse-app-lock-v1'},pin));localStorage.setItem(lockKey,saved);toast('App lock enabled')}
     sessionStorage.removeItem('morse-app-unlocked');show();
   }catch(e){toast('Could not enable app lock')}
 });
 $('#app-unlock').onclick=async()=>{try{await MorseCrypto.openVault(JSON.parse(localStorage.getItem(lockKey)),pinInput.value);hide()}catch(e){error.textContent='Incorrect PIN or damaged lock record.';pinInput.select()}};
 pinInput.addEventListener('keydown',e=>{if(e.key==='Enter')$('#app-unlock').click()});
 $('#app-lock-disable')?.addEventListener('click',async()=>{try{const saved=localStorage.getItem(lockKey);if(!saved)return toast('App lock is not enabled');const pin=prompt('Enter the current app-lock PIN to disable it.');if(pin===null)return;await MorseCrypto.openVault(JSON.parse(saved),pin);localStorage.removeItem(lockKey);sessionStorage.setItem('morse-app-unlocked','1');toast('App lock disabled')}catch(e){toast('Incorrect PIN; app lock remains enabled')}});
 $('#app-lock-panic').onclick=()=>{if(confirm('Panic wipe clears local storage and offline caches on this device. Continue?')){localStorage.clear();sessionStorage.clear();if('caches'in window)caches.keys().then(keys=>Promise.all(keys.map(k=>caches.delete(k))));if('serviceWorker'in navigator)navigator.serviceWorker.getRegistrations().then(rs=>rs.forEach(r=>r.unregister()));location.href='/'}};
}
document.addEventListener('click',e=>{if(e.target.closest('#panic-wipe')){if(confirm('Panic wipe clears this site’s local history, saved encrypted codebook, theme and offline cache on this device. Continue?')){localStorage.clear();sessionStorage.clear();if('caches'in window)caches.keys().then(keys=>Promise.all(keys.map(k=>caches.delete(k))));if('serviceWorker'in navigator)navigator.serviceWorker.getRegistrations().then(rs=>rs.forEach(r=>r.unregister()));toast('Local app data wiped. Reloading…');setTimeout(()=>location.href='/',700)}}});
let logoTaps=0,logoTapTimer=null;document.addEventListener('click',e=>{if(!e.target.closest('.brand-mark'))return;logoTaps++;clearTimeout(logoTapTimer);logoTapTimer=setTimeout(()=>logoTaps=0,1600);if(logoTaps>=3){logoTaps=0;if(confirm('Triple-tap panic wipe: clear this site’s local storage, caches and service worker on this device?')){localStorage.clear();sessionStorage.clear();if('caches'in window)caches.keys().then(keys=>Promise.all(keys.map(k=>caches.delete(k))));if('serviceWorker'in navigator)navigator.serviceWorker.getRegistrations().then(rs=>rs.forEach(r=>r.unregister()));location.href='/'}}});$('#theme').onclick=()=>{document.body.classList.toggle('light');localStorage.setItem('morse-theme',document.body.classList.contains('light')?'light':'dark')};if(localStorage.getItem('morse-theme')==='light')document.body.classList.add('light');$('#menu').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))};document.addEventListener('click',e=>{const a=e.target.closest('a[href^="/"]');if(!a||a.target==='_blank'||e.metaKey||e.ctrlKey||e.shiftKey)return;const u=new URL(a.href);if(u.origin===location.origin){e.preventDefault();history.pushState({},'',u.pathname+u.hash);render()}});window.addEventListener('popstate',render);window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#book=')||location.hash.startsWith('#payload=')||location.hash.startsWith('#room=')||location.hash.startsWith('#/'))render()});if('serviceWorker'in navigator&&location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));render();setupAppLock();
